          long: "\u9f99\u9686\u5f04\u5784\u7b3c\u62e2\u804b\u9647\u80e7\u73d1\u7abf\u830f\u5499\u783b\u5785\u6cf7\u680a\u7643",
          nong: "\u519c\u6d53\u5f04\u8113\u4fac\u54dd",
          shuang: "\u53cc\u723d\u971c\u5b40\u6cf7",
